maxHP(){return 100+15*(this.level-1)}
maxMana(){return 100+10*(this.level-1)}
xpNeeded(){return 150*this.level+10*this.level*(this.level-1)}
monsterSpeed(e){return (e.kind==='bear'?.64:e.kind==='boar'?.91:.8)*(1+.065*Math.max(0,e.level-1))}
moveSpeed(){return 2.5*(1+Math.min(.40,.005*Math.max(0,this.level-1)))*(1+window.KOAExpansion.rank(this,'swift')*.02)}
attackRateBonus(){return Math.min(.60,.004*Math.max(0,this.level-1))}
vocation(){return window.KOAAppearance?.get().vocation||'warrior'}
weaponKind(){return this.sword?'blade':RELICS[this.relicEquipped.sword]?.kind||(this.relicEquipped.sword?'blade':'none')}
