visualGear(){return ((this.armor||this.relicEquipped.armor)?1:0)|((this.helmet||this.relicEquipped.helmet)?2:0)|((this.shield||this.relicEquipped.shield)?4:0)|((this.sword||this.relicEquipped.sword)?8:0)|(['ashBlade','cryptBlade'].includes(this.relicEquipped.sword)?16:0)|(this.relicEquipped.armor?32:0)|(this.relicEquipped.shield?64:0)|(this.relicEquipped.boots?128:0)|(this.relicEquipped.ring?256:0)|(this.relicEquipped.legs?512:0)|(this.weaponKind()==='bow'?1024:0)|(this.weaponKind()==='staff'?2048:0)|(this.weaponKind()==='wand'?4096:0)}
gearBonus(){let attack=0,defense=0,crit=0;for(const id of Object.values(this.relicEquipped)){const v=RELICS[id];if(v){const n=this.expansion.upgrades[id]||0;attack+=(v.attack||0)+((v.attack||0)>0?n*2:0);defense+=(v.defense||0)+((v.defense||0)>0?n*.012:0);crit+=v.crit||0}}return {attack,defense:Math.min(.5,defense+.03*(window.KOAExpansion.rank(this,'bulwark')+window.KOAExpansion.rank(this,'bark'))),crit:Math.min(.4,.1+crit+.02*window.KOAExpansion.rank(this,'precision'))}}
rollRelics(e){const rare=Math.random();if(e.kind==='cobra'&&rare<.10)return ['thornBlade'];if(e.kind==='bear'&&rare<.12)return ['elderStaff'];if(e.kind==='bandido'&&rare<.09)return ['frostBow'];if(e.kind==='esqueleto'&&rare<.12)return ['graveLegs'];if(e.kind==='cavaleiro'&&rare<.18)return ['graveHelm','frostRing'];if(e.sewer)return [];if(e.kind==='rei')return [];if(e.kind==='esqueleto'){const roll=Math.random();return roll<.12?['ironLegs']:roll<.34?['ironMail']:[];}if(e.kind==='cavaleiro')return Math.random()<.4?['cryptBlade']:['ward'];if(e.kind==='guardião')return ['ashRing','ashBlade','frostWand'];const p=Math.random();if(e.kind==='bear')return p<.12?['ironLegs']:p<.32?['hunterBoots']:[];if(e.kind==='boar')return p<.12?['leatherBoots']:p<.25?['fang']:[];if(e.kind==='lobo')return p<.08?['wolfRing']:p<.18?['hunterBoots']:p<.30?['fang']:[];return p<.06?['ashBlade']:p<.16?['ward']:p<.28?['ironMail']:p<.40?['knightBlade']:[]}
