dungeonWall(kind,a,b,x,y){if(window.koaSafe||!window.KOAArchitecture?.dungeonWall)return this.add.image(a,b,'crypt-wall').setOrigin(.5,88/92).setDepth(b);const k=this.archTexture('dungeonWall',kind,(x*3+y)%4);return this.add.image(a,b,k).setOrigin(.5,222/240).setDisplaySize(76,114).setDepth(b)}
