updateResidents(dt){if(this.interior!==null||this.inCrypt||this.inSewer)return;for(const n of this.npcs){if(!n.resident||!n.sprite||Math.hypot(n.x-this.p.x,n.y-this.p.y)>12)continue;n.wait=Math.max(0,n.wait-dt);if(n.wait>0)continue;if(!n.goal){for(let i=0;i<8;i++){const a=Math.random()*Math.PI*2,d=1+Math.random()*2.5,x=n.anchor.x+Math.cos(a)*d,y=n.anchor.y+Math.sin(a)*d;if(this.walkable(x,y)&&this.guardLine(n,{x,y})&&!this.houses.some(h=>Math.hypot(h.door.x-x,h.door.y-y)<.85)){n.goal={x,y};break}}if(!n.goal){n.wait=2;continue}}const dx=n.goal.x-n.x,dy=n.goal.y-n.y,d=Math.hypot(dx,dy);let moving=false;if(d>.08){const step=Math.min(d,.72*dt),x=n.x+dx/d*step,y=n.y+dy/d*step;if(this.walkable(x,y)&&Math.hypot(x-this.p.x,y-this.p.y)>.55){n.x=x;n.y=y;n.phase+=dt*8;n.facing=window.KOA15.direction(dx-dy,(dx+dy)*.5);moving=true}else n.goal=null}else n.goal=null;if(!n.goal)n.wait=2+Math.random()*5;const [a,b]=this.iso(n.x,n.y),key=!window.koaSafe&&window.KOAAppearance?window.KOAAppearance.npcTexture(this,n,n.facing||'south',moving?Math.floor(n.phase)%4:0,0):this.unitTexture(n.role,n.facing||'south',moving?Math.floor(n.phase)%4:0,0);if(key!==n.artKey){n.artKey=key;n.sprite.setTexture(key)}n.sprite.setPosition(a,b).setDepth(b);n.label.setPosition(a,b-77).setDepth(b+1)}}
